--region init
function UIWorldBossMainEntryDialog:InitHandler()
    self.events["EVENT_RequestWorldBossInfoDojo"] = Events.AddListener("EVENT_RequestWorldBossInfoDojo", Bind(self, self.OnEventTriggerWorldBossInfoHandler))
    self.events[Constants.EventNames.WorldBossBegin] = Events.AddListener(Constants.EventNames.WorldBossBegin, Bind(self, self.OnEventTriggerWorldBossBegin))
    self.events[Constants.EventNames.WorldBossEnd] = Events.AddListener(Constants.EventNames.WorldBossEnd, Bind(self, self.OnEventTriggerWorldBossEnd))
    self.events[Constants.EventNames.OverseaWorldBossOneKeyDrawRewardsReq] = Events.AddListener(Constants.EventNames.OverseaWorldBossOneKeyDrawRewardsReq, Bind(self, self.RefreshHurtDrawRedPoint))
    self.events[Constants.EventNames.OverseaWorldBossDrawRewardsReq] = Events.AddListener(Constants.EventNames.OverseaWorldBossDrawRewardsReq, Bind(self, self.RefreshHurtDrawRedPoint))
    self.events[Constants.EventNames.EVENT_WORLD_BOSS_RANK_REQ_END] = Events.AddListener(Constants.EventNames.EVENT_WORLD_BOSS_RANK_REQ_END, Bind(self, self.PlayerRankInfoReqOverHandler))
    self.events[Constants.EventNames.OverseaWorldBossHomeReq] = Events.AddListener(Constants.EventNames.OverseaWorldBossHomeReq, Bind(self, self.HomeReqEventHandler))


    SetButtonAction(self.FontStyleButton, Bind(self, self.OnClickFontStyleButtonHandler))
    SetButtonAction(self.Btncheck, Bind(self, self.OnClickBtnCheckHandler))
    SetButtonAction(self.BtnList, Bind(self, self.OnClickBtnListHandler))
    SetButtonAction(self.BtnReward, Bind(self, self.OnClickBtnRewardHandler))
    SetButtonAction(self.BtnWeather, Bind(self, self.BtnWeatherOnClickHandler))
end

function UIWorldBossMainEntryDialog:InitData()
    WorldBossEntityMgr:RequestWorldBossInfoDojo()
    while not self._requestEnd do
        cs_coroutine.yield_return(Yielders.EndOfFrame)
    end
end
--endregion init

--region handler
function UIWorldBossMainEntryDialog:PlayerRankInfoReqOverHandler()
    self._requestEnd = true
end

function UIWorldBossMainEntryDialog:HomeReqEventHandler()
    self:RefreshWeatherButton()
    self:RefreshCardBonus()
end

function UIWorldBossMainEntryDialog:OnEventTriggerWorldBossInfoHandler()
    self._worldBossInfoDojo = self._overseaWorldBossComponent:GetWorldBossInfoDojo()
    if isNull(self._worldBossInfoDojo) then
        return
    end
    self._overseaWorldBossComponent:SetWorldBossInfoDojo(self._worldBossInfoDojo)
    self:RefreshUI()
end

function UIWorldBossMainEntryDialog:OnEventTriggerWorldBossBegin()
    self:InitData()
end

function UIWorldBossMainEntryDialog:OnEventTriggerWorldBossEnd()
    self:InitData()
end

function UIWorldBossMainEntryDialog:OnClickFontStyleButtonHandler()
    if not self._worldBossInfoDojo.isOpen then
        GameUtils.Toast(localize("活动未开启"))
        return
    end
    local upGroup = self._overseaWorldBossComponent:GetUpGroup()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIFightTeamChoose,
        parameters = {
            levelId = self._worldBossInfoDojo.range,
            upBuffData = upGroup
        }
    }, {
        { id = Constants.UITypeIds.UIWorldBossMainDialog }
    })
end

function UIWorldBossMainEntryDialog:OnClickBtnCheckHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIWorldBossDetailsDialog
    }, {
        { id = Constants.UITypeIds.UIWorldBossMainDialog }
    })
end

function UIWorldBossMainEntryDialog:OnClickBtnListHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIWorldBossRankRewardDialog
    },{})
end

function UIWorldBossMainEntryDialog:OnClickBtnRewardHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIWorldBossDamageBonusDialog
    })
end

function UIWorldBossMainEntryDialog:BtnWeatherOnClickHandler()
    local weatherId = self._overseaWorldBossComponent:GetClimateId()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.WorldBossWeatherBonusDialog, parameters = {weatherId = weatherId}
    })
end
