--region private
function UIWorldBossMainEntryDialog:RefreshUI()
    CriWareUtils.PlayMusicById("bgm_world_boss")
    CfUtils.RefreshTopGoods({})
    CfUtils.FillImage(self.Bg, self._worldBossInfoDojo.modelId)
    --self:RefreshBossDetail()
    self:RefreshFontStyleButton()
    self:RefreshHurtRank()
    self:RefreshHurtDrawRedPoint()
end
