--region helper
function UIWorldBossMainEntryDialog:RefreshHurtDrawRedPoint()
    GameUtils.BindRedPoint(Constants.RedPointConst.ABWorldBossReward, self.BtnReward, true)
end

function UIWorldBossMainEntryDialog:RefreshHurtRank()
    local scrPath = "Game.UI.FightReady.UIWorldBoss.UIWorldBossPlayerRankingsDialog.UIWorldBossPlayerRankingsBehaviour"
    ---@type UIWorldBossPlayerRankingsBehaviour
    self._rankScr = CfUtils.GetLuaScr(self.WorldBossPlayerRankingsDialog.gameObject, scrPath)
    self._rankScr:Refresh()
    CfUtils.SetActive(self.WorldBossPlayerRankingsDialog, true)
end

function UIWorldBossMainEntryDialog:RefreshFontStyleButton()
    CfUtils.SetActive(self.FontStyleButton.transform:Find("ImgBlack").gameObject, not self._worldBossInfoDojo.isOpen)
end

function UIWorldBossMainEntryDialog:RefreshBossDetail()
    CfUtils.FillText(self.TxtName, WorldBossUtils.GetWorldBossNameByScheduleId(self._worldBossInfoDojo.worldBossScheduleId))
    if self._worldBossInfoDojo.isOpen then
        CfUtils.FillText(self.TextTime, localize("离封锁关闭时间_time_", {_time_ = CfUtils.GetTimeHMS(self._worldBossInfoDojo.remainTime)}))
    else
        CfUtils.FillText(self.TextTime, localize("离封锁开启时间_time_", {_time_ = CfUtils.GetTimeHMS(self._worldBossInfoDojo.worldBossStartTime)}))
    end
end

function UIWorldBossMainEntryDialog:RefreshWeatherButton()
    local weather = self._overseaWorldBossComponent:GetClimateId()
    local weatherVo = CfUtils.GetCfVo(AutoIds.IdSetting6222, "WorldBossWeatherVo", weather)
    if isNull(weatherVo) then 
        KTool.SetActive(self.BtnWeather, false)
        return 
    end
    
    KTool.SetActive(self.BtnWeather, true)
    CfUtils.FillText(self.BtnWeatherDescText, weatherVo.name)
    CfUtils.FillImage(self.BtnWeatherImgIcon, weatherVo.climateIcon)
end

function UIWorldBossMainEntryDialog:RefreshCardBonus()
    local upGroup = self._overseaWorldBossComponent:GetUpGroup()
    if not next(upGroup) then
        CfUtils.SetActive(self.RoleUpDesc, false)
        return
    end

    CfUtils.SetActive(self.RoleUpDesc, true)
    for i = 1, 3 do
        local node = self['Role' .. i]
        if isNotNull(node) then
            if upGroup[i] then
                CfUtils.SetActive(node, true)
                local scr = CfUtils.GetLuaScr(node, "Game.UI.FightReady.UIWorldBoss.UIWorldBossMainDialog.UIWorldBossCardBonusNode")
                if isNotNull(scr) then
                    scr:RefreshNode(upGroup[i])
                end
            else
                CfUtils.SetActive(node, false)
            end
        end
    end
end
--endregion helper

return UIWorldBossMainEntryDialog